import React, { useState } from 'react';

export default function HowItWorksView() {
  const [wayToggle, setWayToggle] = useState('dubai');

  return (
    <main className="fade-in hiw-container">
      <div className="hiw-header">
        <h1 className="font-serif">How it works</h1>
        <p>From visiting our local boutique to reserving an elite breed from abroad, we are dedicated to making your journey to pet parenthood seamless and extraordinary.</p>
      </div>

      <div className="hiw-nav-pills">
        <button className="hiw-pill active">1. Your Adoption Journey</button>
        <button className="hiw-pill">2. Our Quality Guarantee</button>
        <button className="hiw-pill">3. Travel & Arrival</button>
        <button className="hiw-pill">4. The TeddyPups Difference</button>
      </div>

      {/* Section 1: Choose Your Way */}
      <section className="hiw-section">
        <div className="hiw-section-top">
          <div>
            <p className="hiw-sub">your journey begins here</p>
            <h2 className="hiw-title font-serif">Bringing your puppy home</h2>
          </div>
          <div className="hiw-toggle">
            <button className={wayToggle === 'dubai' ? 'active' : ''} onClick={() => setWayToggle('dubai')}>
              Local Boutique <small>meet face-to-face</small>
            </button>
            <button className={wayToggle === 'imported' ? 'active' : ''} onClick={() => setWayToggle('imported')}>
              Global Sourcing <small>by special request</small>
            </button>
          </div>
        </div>

        <div className="hiw-split">
          <div>
            {wayToggle === 'dubai' ? (
              <>
                <h3 className="font-serif">Meet your puppy in person</h3>
                <p>Step into our Downtown Dubai showroom and experience the joy of choosing your puppy face-to-face. We source healthy, well-socialized puppies from trusted local breeders, ensuring they're raised with care, proper nutrition, and veterinary checks.</p>
              </>
            ) : (
              <>
                <h3 className="font-serif">Exclusive International Access</h3>
                <p>Searching for a rare miniature companion? We partner exclusively with top-tier, cruelty-free breeders across the globe to secure your ideal puppy. Our specialists manage every detail—from health clearances to international flight logistics—so you don't have to lift a finger.</p>
              </>
            )}
          </div>
          <div className="hiw-illustration">
            🏢 🏙️ 🌇
          </div>
        </div>

        <div className="step-cards">
          <div className="step-card">
            <div className="step-icon" style={{color: '#f59e0b', backgroundColor: '#fef3c7'}}>🔍</div>
            <p className="step-num">Step 1</p>
            <h4>Discover your companion</h4>
            <p>Peruse our curated online gallery of available puppies. Every profile features verified photos, genetic background, age, and comprehensive health records.</p>
          </div>
          <div className="step-card">
            <div className="step-icon" style={{color: '#ef4444', backgroundColor: '#fee2e2'}}>❤️</div>
            <p className="step-num">Step 2</p>
            <h4>Select your favorite</h4>
            <p>Found the one that steals your heart? Dive into their full profile for extended details, or send us a direct message to learn more about their unique personality.</p>
          </div>
          <div className="step-card">
            <div className="step-icon" style={{color: '#3b82f6', backgroundColor: '#dbeafe'}}>🐶</div>
            <p className="step-num">Step 3</p>
            <h4>Connect and bond</h4>
            <p>Schedule a private session in our luxurious viewing lounges to ensure a perfect connection before making your final commitment.</p>
          </div>
          <div className="step-card">
            <div className="step-icon" style={{color: '#10b981', backgroundColor: '#d1fae5'}}>🚚</div>
            <p className="step-num">Step 4</p>
            <h4>Welcome them home</h4>
            <p>Collect your new family member directly from our boutique, or opt for our secure, VIP chauffeur delivery right to your doorstep in Dubai.</p>
          </div>
        </div>
      </section>

      {/* Section 2: Puppy Promise */}
      <section className="hiw-section">
        <div className="promise-box">
          <p className="hiw-sub">our gold standard</p>
          <h2 className="hiw-title font-serif">The TeddyPups<br/>Commitment</h2>

          <div className="promise-grid">
            <div className="promise-item">
              <div className="promise-icon">🏥</div>
              <h4 className="font-serif">Elite Breeding Partners</h4>
              <p>We strictly collaborate with reputable, vetted breeders who prioritize exceptional health, genetics, and animal welfare above all else.</p>
            </div>
            <div className="promise-item">
              <div className="promise-icon">✈️</div>
              <h4 className="font-serif">Complete Visibility</h4>
              <p>Receive comprehensive media updates—including videos, high-resolution photos, and official veterinary clearances—well before your puppy boards their flight.</p>
            </div>
            <div className="promise-item">
              <div className="promise-icon">🛡️</div>
              <h4 className="font-serif">VIP Travel Experience</h4>
              <p>We orchestrate the entire importation and customs process, guaranteeing a smooth, comfortable, and anxiety-free journey for your tiny friend.</p>
            </div>
          </div>
        </div>
      </section>

      {/* Section 3: Delivery */}
      <section className="hiw-section">
        <h2 className="hiw-title font-serif mb-4">Travel &<br/>Collection</h2>
        <p style={{maxWidth: '40rem', color: 'rgba(74, 59, 50, 0.8)', fontSize: '1.125rem', marginBottom: '2rem'}}>
          Whether they are resting in our Downtown Dubai suites or flying first-class from Seoul, your puppy's comfort is our ultimate priority.
        </p>

        <div className="delivery-grid">
          <div>
            <div className="del-item">
              <h4>Instant Match & Takeaway</h4>
              <p>Our resident puppies are ready for immediate adoption. Stop by, meet your match, and leave together on the very same day.</p>
            </div>
            <div className="del-item">
              <h4>Chauffeur Service in Dubai</h4>
              <p>Relax at home while our specialized transport team safely escorts your puppy directly to your residence within the city.</p>
            </div>
            <div className="del-item">
              <h4>Expert International Transit</h4>
              <p>We expertly navigate all complex customs paperwork, flight bookings, and health documentation to ensure a seamless entry into the country.</p>
            </div>
            <div className="del-item">
              <h4>Global Door-to-Door Delivery</h4>
              <p>No matter where you reside, our certified pet relocation partners guarantee your new companion arrives safely and securely across borders.</p>
            </div>
          </div>

          <div className="del-illustration">
             <span style={{fontWeight: 700, fontSize: '0.875rem', zIndex: 10, alignSelf: 'flex-end', paddingBottom: '0.5rem'}}>Korea</span>
             <div className="del-plane">✈️</div>
             <div className="del-path"></div>
             <span style={{fontWeight: 700, fontSize: '0.875rem', zIndex: 10, alignSelf: 'flex-end', paddingBottom: '0.5rem'}}>Dubai</span>
          </div>
        </div>
      </section>

    </main>
  );
}
